const PLANTAS_DATA = [{"nome": "Agave", "cientifico": "Anthalonium Levini", "usosMedicinais": "As folhas frescas, mastigadas, produzem alucinações aterradoras; as folhas secas, mastigadas, produzem visões alegres e de caráter erótico. Muito procurada pelos povos indígenas do Texas e Novo México.", "ocultismo": "O cacto, em todas as suas variedades, traz sorte segundo a crença popular.", "planeta": "Saturno", "signo": "", "colheita": "Deve ser colhida na hora de Saturno.", "elemento": "", "planetasChave": ["Saturno"], "signosChave": []}, {"nome": "Agárico", "cientifico": "Viscum album", "usosMedicinais": "Hoje quase esquecida pela ciência médica, mas com bons resultados em doenças nervosas como convulsões e epilepsia, usada em decocto (5g de material triturado fervido 15 min em meio litro de água, uma xícara a cada 4 horas). Segundo Plínio, sua infusão tomada ao fim do período menstrual favorece a concepção e combate a esterilidade.", "ocultismo": "Os druidas colhiam suas bagas no Natal, em hora astrológica propícia, com grandes cerimônias, usando-as como condensadores magnéticos para curas notáveis. Era cortada com uma foice de ouro consagrada. Planta parasita que simbolizava, entre os druidas, o sacrifício divino e a descida do Espírito à Matéria.", "planeta": "", "signo": "Touro", "colheita": "No Natal, em hora astrológica favorável.", "elemento": "Fria e seca", "planetasChave": [], "signosChave": ["Touro"]}, {"nome": "Abrótono", "cientifico": "Abrotanum", "usosMedicinais": "Planta semelhante ao absinto. Anti-helmíntica, estomacal e estimulante. Recomendada para provocar o fluxo menstrual e facilitar os partos.", "ocultismo": "", "planeta": "Lua", "signo": "Escorpião", "colheita": "Início de abril.", "elemento": "Quente e seco", "planetasChave": ["Lua"], "signosChave": ["Escorpião"]}, {"nome": "Absinto", "cientifico": "Artemisa absinthyum", "usosMedicinais": "Vermífugo e febrífugo. Pode produzir insônia e alucinações terríveis em pessoas muito nervosas.", "ocultismo": "Considerado receptáculo do astral inferior; suas flores secas e queimadas servem de perfume nas evocações de entidades infernais.", "planeta": "Marte", "signo": "Capricórnio", "colheita": "", "elemento": "", "planetasChave": ["Marte"], "signosChave": ["Capricórnio"]}, {"nome": "Acácia", "cientifico": "Acacia", "usosMedicinais": "", "ocultismo": "Árvore sagrada dos egípcios. Na maçonaria simboliza a imortalidade da alma; no grau Rosa-Cruz ensina-se que a cruz do Cristo teria sido feita desta madeira. O suco do fruto, colhido na hora planetária correspondente, é usado nas tintas para desenhar talismãs em pergaminho.", "planeta": "Mercúrio", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Mercúrio"], "signosChave": []}, {"nome": "Açafrão", "cientifico": "Crocus sativus", "usosMedicinais": "Possui várias propriedades curativas, mas seu uso é desaconselhado a quem não é versado na arte de curar.", "ocultismo": "Utilizado em feitiços e perfumes mágicos.", "planeta": "", "signo": "Leão, Peixes ou Câncer", "colheita": "Quando o Sol está em Leão ou Peixes, ou a Lua em Câncer.", "elemento": "", "planetasChave": [], "signosChave": ["Câncer", "Leão", "Peixes"]}, {"nome": "Acanto", "cientifico": "Acanthus mollis", "usosMedicinais": "Planta perene; suas folhas, ricas em suco mucilaginoso, são aperitivas, emolientes e eficazes contra queimaduras.", "ocultismo": "Propriedades mágicas desconhecidas.", "planeta": "Marte", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Marte"], "signosChave": []}, {"nome": "Acônito", "cientifico": "Aconitum napellus", "usosMedicinais": "Planta perigosa; não deve ser usada por leigos.", "ocultismo": "Fria e seca. Usada (misturada com arruda, açafrão e aloés) em fumigações para afastar maus espíritos. Uma das doze plantas dos Rosa-Cruzes. Segundo os gregos, nasceu da baba de Cérbero quando Hércules o tirou dos infernos. Atribui-se-lhe a virtude de fazer renascer os pelos.", "planeta": "Saturno", "signo": "Capricórnio", "colheita": "", "elemento": "Fria e seca", "planetasChave": ["Saturno"], "signosChave": ["Capricórnio"]}, {"nome": "Agnocasto", "cientifico": "Agnus castus", "usosMedicinais": "Paracelso chamava-a de planta satânica e usava seus grãos em infusão para curar os 'ardores da carne'. Suas propriedades afrodisíacas já eram conhecidas pelos atenienses, que colocavam a planta em seus leitos para conservar a continência.", "ocultismo": "", "planeta": "Saturno", "signo": "Câncer", "colheita": "", "elemento": "", "planetasChave": ["Saturno"], "signosChave": ["Câncer"]}, {"nome": "Agrimônia", "cientifico": "Agrimonia eupatoria", "usosMedicinais": "Fria e seca. Vermífuga; folhas adstringentes; cura anginas, nefrites, fluxos leucorréicos e debilidade da bexiga. Em loção, boa contra cataratas, luxações e feridas. Eficaz contra picadas de cobra.", "ocultismo": "Colocadas sobre a cabeça de quem dorme, suas folhas impedem que a pessoa desperte.", "planeta": "", "signo": "", "colheita": "", "elemento": "Fria e seca", "planetasChave": [], "signosChave": []}, {"nome": "Aipo", "cientifico": "Apio graveolens", "usosMedicinais": "Seus grãos são digestivos e eficazes contra flatulências; suas raízes, diuréticas e aperitivas. Em infusão (200g por litro de água), bom remédio para reduzir o leite das mães.", "ocultismo": "Planta sagrada entre os gregos, usada em cerimônias fúnebres. Virtudes mágicas desconhecidas.", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Alcachofra", "cientifico": "Scolymus", "usosMedicinais": "Levemente afrodisíaca. A raiz ou o grão, colhidos quando o Sol entra no quinto grau de Libra, curam fluxos de sangue e dores do ventre. A água do cotão interior conserva os cabelos.", "ocultismo": "", "planeta": "Marte", "signo": "Escorpião", "colheita": "", "elemento": "", "planetasChave": ["Marte"], "signosChave": ["Escorpião"]}, {"nome": "Alho", "cientifico": "Allium sativum", "usosMedicinais": "Anti-helmíntico, estimulante, anti-reumático e expectorante; corrige a menstruação; bom contra hidropisia e mal de pedra; eficaz contra bronquites; aplicado puro, combate sarna e tinha. Paracelso afirmava ter curado doentes de raiva submetendo-os a banhos de vapor após dose de alho.", "ocultismo": "Para se proteger de feitiços, colhem-se sete alhos na hora de Saturno, enfiam-se em um cordão de cânhamo e carregam-se no pescoço por sete sábados. Untar os galhos de uma árvore com alho afasta os pássaros. Para obter alhos sem cheiro, plantar e colher quando a lua não estiver sobre o horizonte.", "planeta": "Saturno", "signo": "", "colheita": "Para amuletos, colher na hora de Saturno.", "elemento": "", "planetasChave": ["Saturno"], "signosChave": []}, {"nome": "Aloés", "cientifico": "Aloé socotrina", "usosMedicinais": "De suas folhas extrai-se um suco que se converte em massa quebradiça cor de alfarroba. Em pequenas doses, aperitivo; em doses maiores, purgante. Não recomendado a crianças ou gestantes. Em loções com vinagre, evita a queda de cabelo.", "ocultismo": "Em pó, misturado com incenso, é usado como perfume para atrair as influências de Júpiter.", "planeta": "Júpiter", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Júpiter"], "signosChave": []}, {"nome": "Alforva", "cientifico": "Trigonella foenum graecum", "usosMedicinais": "Em cataplasmas, a farinha de suas sementes é eficaz contra inchações e inflamações.", "ocultismo": "", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Amieiro", "cientifico": "Betulo nigra", "usosMedicinais": "Suas folhas embranquecem quando a atmosfera tende a chover, funcionando como barômetro natural.", "ocultismo": "O carvão desta madeira é usado para traçar círculos mágicos em evocações.", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Angélica", "cientifico": "Archangelica officinalis", "usosMedicinais": "Chamada Erva-do-Espírito-Santo. Raiz tônica e estimulante, usada contra a debilidade digestiva; propriedades antiespasmódicas, carminativas e estomacais.", "ocultismo": "Boa para prevenir alucinações e fascinação; colocada no pescoço de crianças, defende contra embruxamentos. Colhida na hora de Saturno, as folhas curam a gota; a raiz, arrancada nas horas de Sol ou Marte sob Leão, cura gangrena e mordidas venenosas.", "planeta": "", "signo": "Leão e Aquário", "colheita": "Fim de agosto.", "elemento": "", "planetasChave": [], "signosChave": ["Leão", "Aquário"]}, {"nome": "Anis-verde", "cientifico": "Pimpinella anisum", "usosMedicinais": "Seus frutos ativam estômago e intestinos; diurético e atemperante. Em loções, melhora a vista; em infusão com vinho e açafrão, cura oftalmias.", "ocultismo": "Propriedades mágicas desconhecidas; mais eficaz se colhida na hora de Mercúrio sob Gêmeos ou Virgem.", "planeta": "Mercúrio", "signo": "Gêmeos ou Virgem", "colheita": "", "elemento": "", "planetasChave": ["Mercúrio"], "signosChave": ["Gêmeos", "Virgem"]}, {"nome": "Aristolóquia", "cientifico": "Aristolochia", "usosMedicinais": "Pulmonar, diurética, emenagoga, detersiva e vulnerária. Favorece a expulsão das secundinas e cura fluxos uterinos. Em loções com vinho, cura sarna e seca chagas.", "ocultismo": "O fumo de seus grãos acalma epilépticos e possessos, e desfaz o feitiço da agulheira (impotência feiticeira).", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Arnica", "cientifico": "Arnica montana", "usosMedicinais": "Alivia tonturas; bons resultados em catarros pulmonares crônicos sem febre. Remédio externo popular contra golpes e quedas, em tintura diluída.", "ocultismo": "Uma das doze plantas dos antigos Rosa-Cruzes.", "planeta": "Sol", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Sol"], "signosChave": []}, {"nome": "Artemísia", "cientifico": "Artemisa vulgaris", "usosMedicinais": "Chamada também erva-de-São-João. Emenagoga, estimulante e tônica; eficaz contra epilepsia. Fervida com vinho em pequenas doses, evita abortos; indicada para provocar menstruação.", "ocultismo": "Uma das doze plantas da antiga Rosa-Cruz. Colhida em dia de São João e pendurada num roble torna o campo fértil; colhida de noite, é poderoso amuleto contra sortilégios. Queimada como defumador, desfaz o feitiço da agulheira. Diversas tradições populares europeias usam-na para proteger casas, gado e plantações de bruxedos e granizo.", "planeta": "", "signo": "", "colheita": "Dia de São João, ou qualquer sexta-feira antes do nascer do sol.", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Aveia comum", "cientifico": "Avena sativa", "usosMedicinais": "Contra reumatismo, em cataplasmas quentes com vinho; contra hidropisia, em decocto; excelente diurético; contra chagas pútridas, em cataplasma com levedura de cerveja. Para sarna, deitar-se nu sobre um campo de aveia e esfregar a pele com seus talos molhados em água de fonte.", "ocultismo": "Propriedades mágicas desconhecidas.", "planeta": "Sol e Lua", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Sol", "Lua"], "signosChave": []}, {"nome": "Aveleira (Hamamélis)", "cientifico": "Hamamelis virginica", "usosMedicinais": "Chamada popularmente Aveleira-da-Feiticeira. Notável propriedade anti-hemorroidal; usada em pomada e tintura.", "ocultismo": "A varinha-de-condão tradicional é feita de aveleira silvestre, cortada ao nascer do sol em junho (ou na lua cheia do mesmo mês). Usada para detectar água, metais ou tesouros escondidos. O padre Kircher descreve um método específico de confecção e uso da varinha bifurcada.", "planeta": "Mercúrio", "signo": "", "colheita": "Junho, ao nascer do sol.", "elemento": "", "planetasChave": ["Mercúrio"], "signosChave": []}, {"nome": "Azedinha-da-horta", "cientifico": "Rumex acetosa", "usosMedicinais": "Depurativa e refrescante. A raiz, macerada em vinagre forte, é remédio contra erupções de pele. O suco fresco trata úlceras pútridas e gangrenosas.", "ocultismo": "", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Azinheira", "cientifico": "Quercus ruber", "usosMedicinais": "Usa-se a casca, adstringente; contra diarreias serosas, hemorragias, leucorréias e hemoptises; em grandes doses, contra tuberculose pulmonar.", "ocultismo": "De um antigo grimório: para ter sorte nos negócios, queimar cinco bolotas colhidas no domingo em sua hora planetária e reduzi-las a pó; guardar em bolsa de seda amarela e portar consigo — o 'amuleto do Sol'.", "planeta": "Sol", "signo": "", "colheita": "Domingo, em hora planetária do Sol.", "elemento": "", "planetasChave": ["Sol"], "signosChave": []}, {"nome": "Bardana", "cientifico": "Lappa maior", "usosMedicinais": "Fria e seca. Atua sobre doenças de pele, úlceras, gota e sífilis; bons resultados em cálculos renais e cólicas hepáticas. As folhas em cozimento tratam a tinha.", "ocultismo": "Propriedades mágicas desconhecidas.", "planeta": "", "signo": "", "colheita": "", "elemento": "Fria e seca", "planetasChave": [], "signosChave": []}, {"nome": "Beladona", "cientifico": "Atropa belladona", "usosMedicinais": "Fria e úmida. Planta muito ativa; como o acônito e o meimendro, seu uso deve ser sempre dirigido por um médico.", "ocultismo": "Propriedades semelhantes ao meimendro; uma das plantas que compõem a tradicional pomada das bruxas. Folhas secas e trituradas, misturadas com açafrão e cânfora, formam perfume mágico para afugentar larvas do astral.", "planeta": "Saturno e Vênus", "signo": "Escorpião", "colheita": "", "elemento": "Fria e úmida", "planetasChave": ["Saturno", "Vênus"], "signosChave": ["Escorpião"]}, {"nome": "Betônica", "cientifico": "Betonica officinalis", "usosMedicinais": "Ingerida, produz defecação abundante. Externamente, eficaz em úlceras varicosas e chagas infectadas, em cozimento.", "ocultismo": "Indicada contra o embruxamento.", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Bistorta", "cientifico": "Poligonum bistorta", "usosMedicinais": "Sua raiz é poderoso adstringente contra diarreias crônicas; em gargarejos, cura inflamações da boca; em loções, cicatriza chagas; tônico contra tuberculose incipiente, tomada com vinho.", "ocultismo": "Virtudes mágicas desconhecidas.", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Briônia", "cientifico": "Bryonia alba", "usosMedicinais": "Conhecida como nabo-galante ou morte-do-diabo. Uso interno perigoso. Em pomada com azeite, usada contra inchaços de garganta, peito, ventre e pernas.", "ocultismo": "Usada em cerimônias de magia negra. Columela atribui-lhe a virtude de afastar raios, colocando um raminho em cada ponto cardeal do edifício a proteger.", "planeta": "Mercúrio", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Mercúrio"], "signosChave": []}, {"nome": "Buglossa", "cientifico": "Anchusa itálica", "usosMedicinais": "O suco das folhas, misturado com açúcar formando xarope, cura palpitações do coração. As flores são recomendáveis contra bronquites leves e catarros ligeiros.", "ocultismo": "Propriedades mágicas desconhecidas.", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Caldo-branco", "cientifico": "Verbascus thapsus", "usosMedicinais": "Usam-se folhas e flores contra asma, tenesmos de sangue e tosse, em infusão. Em alguns casos de sífilis, e em infusão com leite, contra tuberculose pulmonar. Frescas, aplicadas externamente, curam feridas.", "ocultismo": "", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Camélia", "cientifico": "Camelli", "usosMedicinais": "Sem aplicações terapêuticas conhecidas.", "ocultismo": "Destilada, produz azeite de grande valor mágico para alimentar lâmpadas usadas em ritos teúrgicos e evocações angélicas. Benéfica em sessões espirituais, favorecendo comunicações com espíritos elevados.", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Cana", "cientifico": "Arundo donax", "usosMedicinais": "Usada como depurativo suave e para suspender a lactação, em decocto da raiz.", "ocultismo": "Crença popular: para curar um deslocamento de membro, basta colocar sobre ele dois pedaços de cana cortados com essa intenção, encaixados um dentro do outro, com fé inquebrantável na prática.", "planeta": "Mercúrio", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Mercúrio"], "signosChave": []}, {"nome": "Canela", "cientifico": "Cinnamomum zeylanicum", "usosMedicinais": "Mais usada na culinária que na terapêutica. Excelente para provocar menstruação; serve contra indigestões, emoções fortes, síncopes e espasmos, em tintura.", "ocultismo": "Empregada nos perfumes mágicos do Sol e em certos filtros de amor (uso que o mago branco deve evitar).", "planeta": "Sol", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Sol"], "signosChave": []}, {"nome": "Cânhamo hindu", "cientifico": "Cannabis indica", "usosMedicinais": "Muito ativa; não deve ser usada sem orientação médica, sob risco de envenenamento. Em tintura, contra coqueluche, neuralgias e cefaleias; sedativo em úlceras estomacais; hipnótico.", "ocultismo": "Produz extrato gorduroso (haxixe) que, segundo o livro, provoca êxtases místicos, diabólicos ou eróticos conforme a moralidade e mentalidade de quem o usa.", "planeta": "Saturno", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Saturno"], "signosChave": []}, {"nome": "Cebola", "cientifico": "Allium cepa", "usosMedicinais": "Diurética, estimulante, vermífuga, expectorante e afrodisíaca; contra retenção de urina, lombrigas, catarro pulmonar, tosse bronquial e escorbuto. Crua, contra pneumonias; o sumo em fricções detém a queda de cabelo; cozida, alivia dor de ouvido.", "ocultismo": "", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Cebola-albarrã", "cientifico": "Scilla marítima", "usosMedicinais": "Oferece sérios perigos; não recomendada para a medicina caseira.", "ocultismo": "Propriedades ocultas desconhecidas.", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Celedônia", "cientifico": "Chelinoum majus", "usosMedicinais": "Perigosa por via interna; o suco (extraído malhando a raiz) extirpa verrugas; cataplasma sobre a pélvis para a supressão das regras. Atenção: o uso popular de aclarar a vista com o sumo oferece sério risco de cegueira.", "ocultismo": "Sua raiz, colocada sobre a cabeça de um doente febril, fá-lo-á cantar se for morrer, e chorar se viver.", "planeta": "Sol", "signo": "Sagitário", "colheita": "", "elemento": "", "planetasChave": ["Sol"], "signosChave": ["Sagitário"]}, {"nome": "Centáurea menor", "cientifico": "Erythrae centaurium", "usosMedicinais": "Talos e flores são tônico amargo na debilidade digestiva; contra febres intermitentes, flatulências e gota, em infusão. Externamente, sobre úlceras escrofulosas e feridas.", "ocultismo": "Segundo a lenda, descoberta pelo centauro Quíron. Antidemoníaca e dotada de grandes virtudes mágicas; deve ser colhida com palavras de encantamento (Plínio). Um antigo grimório atribuído a Alberto Magno descreve usos para provocar visões e impressões aterradoras.", "planeta": "Júpiter", "signo": "Leão", "colheita": "", "elemento": "", "planetasChave": ["Júpiter"], "signosChave": ["Leão"]}, {"nome": "Cevada", "cientifico": "Hordeum vulgare", "usosMedicinais": "Nutritiva, emoliente e muito refrescante, em decocto. A farinha, em cataplasmas, dissipa e atenua humores.", "ocultismo": "Suas espigas (Yava em sânscrito) eram oferecidas pelos bramanes em sacrifícios aos deuses.", "planeta": "Sol", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Sol"], "signosChave": []}, {"nome": "Chicória", "cientifico": "Chicorium Intibus", "usosMedicinais": "Quente e seca. Depurativa e laxante, contra digestões lentas; uso prolongado cura cólicas hepáticas.", "ocultismo": "Colhida de joelhos no dia de São João Batista, antes do nascer do sol, pronunciando três vezes o nome sagrado Tetragrammaton, torna-se poderoso amuleto contra ciladas diabólicas e sortilégios para toda a casa onde for guardada.", "planeta": "", "signo": "", "colheita": "Dia de São João Batista, antes do amanhecer.", "elemento": "Quente e seca", "planetasChave": [], "signosChave": []}, {"nome": "Cicuta", "cientifico": "Conium maculatum", "usosMedicinais": "Sumamente venenosa; evitar uso interno sem orientação médica. Pode ser confundida com cerefólio e salsa — atenção às diferenças de folha e cheiro. Em caso de envenenamento, provocar vômito e administrar ácidos vegetais diluídos (limão, vinagre). Inócua para cabras e carneiros; tóxica para coelhos, bois e cavalos e para o homem.", "ocultismo": "Faz parte da pomada dos bruxos. Preparada com vinho, produz sono letárgico em pássaros.", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Cinoglossa", "cientifico": "Cinoglossum officinalis", "usosMedicinais": "Conhecida como língua-de-porco. Calmante, peitoral, narcótica e antidiarreica; excelente contra catarros bronquiais, em decocto. As folhas em cataplasma tratam inflamações de pele e queimaduras.", "ocultismo": "Trazida consigo, sua raiz reconcilia com inimigos e atrai a simpatia dos semelhantes (Porta).", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Cipreste", "cientifico": "Cupressus sempervirens", "usosMedicinais": "Sua decocção (das pinhas/galhas) evita o aparecimento de cabelos brancos por mais tempo.", "ocultismo": "Símbolo da morte; coroava a fronte de Plutão. Sua madeira é usada na construção da mesa triangular de certos trabalhos de bruxaria, e queimada com ervas e drogas em evocações aos elementais.", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Coca", "cientifico": "Erythroxylum coca", "usosMedicinais": "Excitante como café ou chá; tonificante para neurastênicos e convalescentes; mitiga fome e cansaço; já foi indicada para reduzir obesidade. Dela se extrai a cocaína.", "ocultismo": "Considerada sagrada pelos antigos peruanos, queimada em altares ao Sol. Segundo o ocultista Estanislau de Guaita, injeções de cocaína podem constituir um verdadeiro pacto com seres do astral.", "planeta": "Saturno e Sol", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Saturno", "Sol"], "signosChave": []}, {"nome": "Coclearia", "cientifico": "Coclearia officinalis", "usosMedicinais": "Antiescorbútica; recomendada contra afecções pulmonares, catarros bronquiais e da bexiga e flores brancas, em infusão.", "ocultismo": "Propriedades mágicas desconhecidas.", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Coentro", "cientifico": "Coriandrum sativum", "usosMedicinais": "Usado contra histerismo, afecções gastrointestinais, cefaleia e febres quartãs, em infusão de seus frutos; melhora também o sabor da cerveja.", "ocultismo": "Os frutos, reduzidos a pó e misturados com almíscar, açafrão e incenso, formam perfume de Vênus muito eficaz em práticas de magia sexual; bom para defumar amuletos e talismãs amorosos (Agrippa).", "planeta": "Vênus", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Vênus"], "signosChave": []}, {"nome": "Consólida", "cientifico": "Symphytum officinalis", "usosMedicinais": "Conhecida como Grande Consolda, Orelha-de-burro, etc. Atribui-se-lhe a propriedade de consolidar fraturas. Em infusão, contra hemoptise e diarreia; em fomentações, queimaduras e feridas; em emplastos, deslocações.", "ocultismo": "Quente e seca. Planta consagrada pelos gregos a Juno (Hebe), rainha dos deuses.", "planeta": "Vênus", "signo": "Sagitário ou Aquário", "colheita": "", "elemento": "Quente e seca", "planetasChave": ["Vênus"], "signosChave": ["Sagitário", "Aquário"]}, {"nome": "Corriola", "cientifico": "Calystegia sepium", "usosMedicinais": "Seu suco leitoso é purgante eficaz; suas folhas, purgantes mais brandos. A raiz é indicada contra paralisia incipiente.", "ocultismo": "Aplicadas a uma chaga pisada e depois deixadas em lugar úmido, suas folhas operam a cura magneticamente. Em infusão com vinho, constitui filtro de amor que conserva a harmonia entre namorados. Trazendo-se sua raiz, evitam-se doenças de visão.", "planeta": "Júpiter e Sol", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Júpiter", "Sol"], "signosChave": []}, {"nome": "Couve", "cientifico": "Brassica oleracea", "usosMedicinais": "Considerada remédio universal pelos antigos. Hipócrates prescrevia-a cozida com mel contra cólicas. Folhas cozidas e quentes contra dores lombares e infartos mamários; em cataplasma, contra dores reumáticas; as sementes são vermífugas.", "ocultismo": "A couve vermelha (Lombarda), comida antes de um banquete, evita o mal-estar do vinho em excesso.", "planeta": "Câncer e Escorpião; a couve vermelha sob Lua e Júpiter", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Júpiter", "Lua"], "signosChave": []}, {"nome": "Cravinhos", "cientifico": "Eugenia cariphylla", "usosMedicinais": "Conhecidos como Cravos-de-especiaria. Tônicos, estomacais, cordiais e estimulantes, em infusão ou tintura; em fricções, contra paralisia e fraqueza muscular; alivia momentaneamente dor de dentes (não recomendado como remédio habitual).", "ocultismo": "Quente e seco. Sua essência é usada em trabalhos de magia negra; associada ao fósforo, atrai larvas astrais. Conservada na boca, fortalece a força nêurica de um hipnotizador. Empregada também em magia sexual.", "planeta": "", "signo": "", "colheita": "Quando o Sol está em Peixes ou a Lua em Câncer.", "elemento": "Quente e seco", "planetasChave": [], "signosChave": []}, {"nome": "Culantrilho", "cientifico": "Adianthum capillus", "usosMedicinais": "Chamado Culantrilho-do-poço; cresce em paredes de poços e fendas úmidas. Usado fresco, facilita a expectoração, acalma dores do peito e favorece a menstruação. Em loções, tonifica o couro cabeludo.", "ocultismo": "A coroa de Plutão era formada por suas folhas.", "planeta": "Saturno", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Saturno"], "signosChave": []}, {"nome": "Damiana", "cientifico": "Turner aphrodisiaca", "usosMedicinais": "Diurética e afrodisíaca; bom tônico nervoso, indicada em neurastenia, convalescenças e impotência; estimulante das funções cerebrais; útil em dispepsia, gastralgia e albuminúria pós-escarlatina.", "ocultismo": "Propriedades mágicas desconhecidas.", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Dentes-de-leão", "cientifico": "Taraxacum dens leonis", "usosMedicinais": "Folhas e raiz usadas em decocto; acalma a tosse e irritações do peito; excelente febrífugo e sudorífico; favorece a função biliar e ajuda em infartos hepáticos e icterícia.", "ocultismo": "", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Ditamo branco", "cientifico": "Dictamus albus", "usosMedicinais": "Conhecido como freixinho. Balsâmico e sedativo; estimula a digestão e regulariza o fluxo menstrual; suas folhas em compressas são boas para gestantes.", "ocultismo": "Uma coroa de suas folhas, colocada na cabeça de uma pessoa magnetizada, favorece o desenvolvimento da clarividência sonambúlica. A raiz seca, queimada, ajuda o trabalho do magnetizador.", "planeta": "Sol", "signo": "Câncer", "colheita": "", "elemento": "", "planetasChave": ["Sol"], "signosChave": ["Câncer"]}, {"nome": "Ênula-campana", "cientifico": "Inula Helenium", "usosMedicinais": "Usam-se rizoma e raiz contra catarros bronquiais, irregularidades menstruais, leucorreia, falta de apetite e pneumonias; o pó, contra doenças do baço; em loções, contra úlceras.", "ocultismo": "Segundo o grimório 'Os Segredos do Pequeno Alberto', colhida e preparada com âmbar cinzento na noite de São João, em contato com a pele da pessoa amada, despertaria nela amor irresistível.", "planeta": "", "signo": "", "colheita": "Noite de São João, à meia-noite.", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Erva-de-Santa-Maria", "cientifico": "Tanacetum vulgare", "usosMedicinais": "Infusão de pontas floridas corrige irregularidades menstruais.", "ocultismo": "", "planeta": "", "signo": "", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": []}, {"nome": "Erva-gateira", "cientifico": "Nepeth cataria", "usosMedicinais": "Pontas floridas usadas contra fraqueza consuntiva, languidez, escorbuto, neuralgias, síncopes e menstruação anormal; anti-histérica, em infusão.", "ocultismo": "Colhida sob aspecto favorável e sabendo extrair o 'arcano', como indica Paracelso, constitui poção que tonifica o corpo e proporciona longa vida.", "planeta": "Mercúrio", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Mercúrio"], "signosChave": []}, {"nome": "Erva-moura", "cientifico": "Solanum nigrum", "usosMedicinais": "Suas bagas são levemente narcóticas, podendo causar acidentes graves; uso interno não recomendado. Tem propriedades sedativas e emolientes.", "ocultismo": "As bagas, misturadas a ramos de mirta e lançadas sobre brasas, formam perfume mágico para afugentar larvas do plano astral.", "planeta": "", "signo": "Libra", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": ["Libra"]}, {"nome": "Escabiosa", "cientifico": "Succina pratensis", "usosMedicinais": "Sudorífica e depurativa, popular no tratamento de varíola, sarampo, escarlatina e febres pútridas, em decocto. Em lavagens vaginais, contra leucorreia; em uso externo, lava úlceras.", "ocultismo": "Propriedades ocultas desconhecidas.", "planeta": "Mercúrio", "signo": "Touro ou Libra; as pontas sob Áries", "colheita": "", "elemento": "Fria e seca", "planetasChave": ["Mercúrio"], "signosChave": ["Áries", "Touro", "Libra"]}, {"nome": "Espinheiro cervical", "cientifico": "Rhamnus catharticus", "usosMedicinais": "Bagas com cheiro desagradável; purgante enérgico, usado como derivativo intestinal em cardíacos e urêmicos; útil em apoplexia e congestão cerebral; contra lombrigas.", "ocultismo": "Quente e seco. Planta consagrada a Saturno; emblema da invenja. Diz-se ter sido usada para confeccionar a coroa de espinhos de Cristo. Simboliza, em certos ritos, a virgindade, o pecado e a humilhação. Seus ramos com frutos, colados a portas e janelas, neutralizam bruxos e impedem a entrada de maus espíritos.", "planeta": "Saturno", "signo": "Libra", "colheita": "", "elemento": "Quente e seco", "planetasChave": ["Saturno"], "signosChave": ["Libra"]}, {"nome": "Estramônio", "cientifico": "Datura stramonium", "usosMedicinais": "Planta perigosíssima; recomenda-se apenas as folhas dessecadas, fumadas em cigarros, contra asma, deixando demais aplicações a critério médico.", "ocultismo": "Muito usada na magia negra; os franceses a chamam 'erva-do-diabo'. Entra em grande quantidade na composição da pomada dos bruxos usada para o Sabá (Conciliábulo).", "planeta": "Saturno", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Saturno"], "signosChave": []}, {"nome": "Faia", "cientifico": "Fagus sylvatica", "usosMedicinais": "Usa-se a casca; aperitiva e antifebrífuga, em decocto; em dose maior, purgante e vomitiva.", "ocultismo": "O talo reduzido a pó serve de perfume para atrair influências saturninas.", "planeta": "Júpiter e Saturno", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Saturno", "Júpiter"], "signosChave": []}, {"nome": "Fava", "cientifico": "Faba vulgaris", "usosMedicinais": "Sua decocção é boa contra mal de pedra; o emplasto de sua farinha resolve tumores das partes sexuais; a farinha alivia queimaduras de sol e escaldaduras.", "ocultismo": "Segundo a escola pitagórica, suas flores levam a marca dos infernos. Colhida em fins de outubro, está sob os auspícios de Escorpião com Mercúrio; o fruto é de Saturno e da Lua.", "planeta": "Saturno e Lua", "signo": "Escorpião", "colheita": "Fim de outubro.", "elemento": "", "planetasChave": ["Saturno", "Lua"], "signosChave": ["Escorpião"]}, {"nome": "Feto macho", "cientifico": "Polystichum filix mas", "usosMedicinais": "Usa-se o rizoma, dulcíssimo e nauseabundo; considerado o melhor expulsor de tênia/solitária, embora às vezes ineficaz para a tênia de origem suína. Em tratado antigo: cozida em vinho, abre obstruções do baço e cura melancolia.", "ocultismo": "Simboliza a humildade; tem amplas aplicações na magia negra, destruindo pesadelos e afastando raios e feitiços. O tratado 'Traité des Superstitions' de J.B. Thiers (séc. XVII) descreve longo ritual para a colheita do feto na véspera de São João, com proteção religiosa, círculo mágico e ladainha angélica, e atribui à semente do feto a virtude de curar possessões e doenças quando tocada com fé.", "planeta": "Saturno", "signo": "Sagitário", "colheita": "Véspera de São João, à meia-noite, segundo ritual descrito.", "elemento": "", "planetasChave": ["Saturno"], "signosChave": ["Sagitário"]}, {"nome": "Figueira", "cientifico": "Ficus carica", "usosMedicinais": "Usam-se os frutos e a casca verde. Os figos secos são emolientes e peitorais; curam calos e abrandam tumores da boca. A casca fresca detém hemorragias nasais.", "ocultismo": "Coroava Saturno; árvore sagrada entre os romanos, dedicada a Mercúrio pelos gregos e a Baco pelos espartanos; na Índia, consagrada a Vishnu. Um ramo colhido sob o aspecto planetário adequado acalma a fúria dos touros. A sicomancia era uma forma de adivinhação com folhas de figueira.", "planeta": "Fruto branco: Júpiter e Vênus; fruto negro: Saturno", "signo": "Aquário", "colheita": "", "elemento": "", "planetasChave": ["Saturno", "Júpiter", "Vênus"], "signosChave": ["Aquário"]}, {"nome": "Funcho", "cientifico": "Foeniculum vulgare", "usosMedicinais": "Propriedades parecidas às do anis; carminativo, útil na atonia digestiva com histerismo e hipocondria; bom para aumentar a secreção de leite. As folhas em resolutivos; a raiz, diurética.", "ocultismo": "Quente e úmido.", "planeta": "", "signo": "Peixes ou Aquário", "colheita": "", "elemento": "Quente e úmido", "planetasChave": [], "signosChave": ["Aquário", "Peixes"]}, {"nome": "Gatunha", "cientifico": "Ononis campestris", "usosMedicinais": "Conhecida como unhas-de-gato. Aperitiva e estomacal; usam-se as raízes em decocto.", "ocultismo": "Colhida sob conjunção de Marte e Júpiter, constitui poderoso talismã contra acidentes, ciladas e ladrões, e evita rixas.", "planeta": "Marte e Júpiter", "signo": "", "colheita": "Sob conjunção de Marte e Júpiter.", "elemento": "", "planetasChave": ["Júpiter", "Marte"], "signosChave": []}, {"nome": "Genciana", "cientifico": "Gentiana lutea", "usosMedicinais": "Combate artritismo, clorose, debilidade estomacal, escrófulas, febres intermitentes, gota e lombrigas, em infusão, tintura ou vinho conforme a doença.", "ocultismo": "Quente e seca. A espécie de montanha era utilizada pelos antigos Rosa-Cruzes em suas cerimônias. Dedicada a São Pedro.", "planeta": "Sol", "signo": "Leão", "colheita": "", "elemento": "Quente e seca", "planetasChave": ["Sol"], "signosChave": ["Leão"]}, {"nome": "Girassol", "cientifico": "Helianthus (do grego Hélios/Sol e tropos/girar)", "usosMedicinais": "", "ocultismo": "Volta-se para seguir o curso do Sol; consagrado a Apolo; uma das doze plantas mágicas da antiga Fraternidade Rosa-Cruz. Entregue a uma sonâmbula magnetizada junto com seu caule, diz-se que desenvolve nela visão orgânica interna (metagnose) e capacidade de interpretar sonhos (onirocrítica).", "planeta": "Sol", "signo": "Leão", "colheita": "", "elemento": "", "planetasChave": ["Sol"], "signosChave": ["Leão"]}, {"nome": "Heléboro negro", "cientifico": "Helleborus niger", "usosMedicinais": "Conhecido como erva-de-Natal, erva-do-inferno e rosa-do-fogo. Purgante violento, vermífugo e emenagogo; uso terapêutico perigoso, não recomendado a leigos. Paracelso descreve longamente suas virtudes em diversas preparações (pó, xarope, quintessência, tintura).", "ocultismo": "Uma das plantas mais usadas por bruxos; sua raiz, colhida na hora de Saturno, é lançada sobre brasas em evocações infernais. Pendurada no pescoço de uma criança, preserva-a do mau-olhado, e se a criança já estiver enfeitiçada, o sortilégio se desfaz (Agrippa).", "planeta": "Saturno", "signo": "", "colheita": "Hora de Saturno.", "elemento": "", "planetasChave": ["Saturno"], "signosChave": []}, {"nome": "Hissopo", "cientifico": "Hyssopus officinalis", "usosMedicinais": "Folhas e pontas usadas contra debilidade digestiva, gastralgia e cólicas flatulentas; estimula o apetite; expectorante em catarros pulmonares crônicos; em gargarejos, cura anginas; usado para facilitar partos; em loções, golpes e contusões.", "ocultismo": "", "planeta": "Sol", "signo": "Leão", "colheita": "", "elemento": "", "planetasChave": ["Sol"], "signosChave": ["Leão"]}, {"nome": "Incenso", "cientifico": "Incensum (Juniperus thurifera)", "usosMedicinais": "Usado externamente em pó sobre úlceras malignas; em emplastos contra entorses e golpes; em defumações para reumatismo.", "ocultismo": "Segundo a mitologia, surgiu de Leucótoe, transformada por Apolo em arbusto de incenso. Usado desde a Antiguidade na purificação de templos e culto divino; misturado com benjoim, almíscar, estoraque e âmbar, forma perfume mágico para evocações teúrgicas e sessões espíritas.", "planeta": "Sol e Júpiter", "signo": "Leão", "colheita": "", "elemento": "", "planetasChave": ["Júpiter", "Sol"], "signosChave": ["Leão"]}, {"nome": "Ipecacuanha", "cientifico": "Cephaelis ipecacuanha", "usosMedicinais": "Usa-se a raiz; provoca vômito após náuseas e salivação; útil em indigestão gástrica e princípio de envenenamento; fluidifica expectoração em bronquite e pneumonia; excelente contra disenteria aguda, em decocto.", "ocultismo": "", "planeta": "Lua e Sol", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Sol", "Lua"], "signosChave": []}, {"nome": "Íris", "cientifico": "Iris", "usosMedicinais": "Aplicações terapêuticas desconhecidas.", "ocultismo": "Suas flores simbolizam a paz, como o arco-íris. Colhidas na hora de Vênus, possuem virtude notável: colocado um ramo sob o travesseiro de criança virgem durante o sono, produz sonhos proféticos de grande certeza.", "planeta": "Vênus", "signo": "Libra", "colheita": "Hora de Vênus.", "elemento": "", "planetasChave": ["Vênus"], "signosChave": ["Libra"]}, {"nome": "Jacinto", "cientifico": "Hyacinthus orientalis", "usosMedicinais": "Não usado em medicina oficial. Um livro de segredos do século XVI afirma que o suco da raiz impede o desenvolvimento piloso e retarda a puberdade, e que a raiz fervida cura tumores testiculares.", "ocultismo": "Cultivo doméstico em garrafa de água, renovada periodicamente, descrito como agradável entretenimento de inverno.", "planeta": "Sol e Vênus", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Sol", "Vênus"], "signosChave": []}, {"nome": "Junípero", "cientifico": "Juniperus communis", "usosMedicinais": "As bagas são excelentes diuréticas, recomendadas contra cálculos renais e hidropisia; anticatarrais; eficazes contra asma e bronquite; também usadas na fabricação do licor 'genebra'.", "ocultismo": "Um ramo afugenta cobras por portar o signo da Trindade. Queimado com incenso, purifica o ambiente de miasmas, afasta entidades maléficas do astral e cura possessos.", "planeta": "Vênus", "signo": "Gêmeos", "colheita": "", "elemento": "", "planetasChave": ["Vênus"], "signosChave": ["Gêmeos"]}, {"nome": "Kouso", "cientifico": "Brayera anthelmintica", "usosMedicinais": "Usam-se as inflorescências femininas dessecadas e pulverizadas; purgantes e notável expulsor de tênia, em infusão.", "ocultismo": "Árvore sagrada dos hindus, indispensável em atos religiosos e ascéticos. Suas flores secas, queimadas, ajudam o desenvolvimento de forças psíquicas e o aperfeiçoamento mediúnico.", "planeta": "Sol", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Sol"], "signosChave": []}, {"nome": "Lírio", "cientifico": "Lilium chrynostates", "usosMedicinais": "Segundo a medicina antiga: o pólen cura queimaduras; a água destilada alivia dores do parto e males da vista; os bulbos fervidos com pão amadurecem abscessos.", "ocultismo": "Símbolo da castidade; Gabriel o leva a Maria. Imagem da Criação universal. Na Idade Média acreditava-se que seu pólen dissolvido em água ou vinho revelava se uma jovem não era casta. A raiz, pendurada no pescoço, reconcilia amantes separados.", "planeta": "Júpiter, Vênus e Lua", "signo": "Áries ou Touro", "colheita": "Quando Lua ou Vênus estão em Áries ou Libra.", "elemento": "Frio e seco", "planetasChave": ["Júpiter", "Vênus", "Lua"], "signosChave": ["Áries", "Touro"]}, {"nome": "Loto", "cientifico": "Lotus", "usosMedicinais": "", "ocultismo": "Mesmo significado religioso do lírio. Sagrado no Egito, na Índia e em outras culturas; chamado de 'Filho do Universo que leva em seu seio a semelhança da Mãe'. Os egípcios o associavam ao renascimento do Sol e à Ressurreição.", "planeta": "Sol", "signo": "Leão", "colheita": "", "elemento": "", "planetasChave": ["Sol"], "signosChave": ["Leão"]}, {"nome": "Loureiro-cerejeira", "cientifico": "Prunus laurus cerasus", "usosMedicinais": "Usam-se as folhas, que contêm ácido cianídrico, veneno potente — uso interno desaconselhado a leigos.", "ocultismo": "Um dos vegetais mais usados em trabalhos de feitiçaria; o livro descreve um ritual malévolo com azeite e três raminhos colocados em cruz na hora de Saturno.", "planeta": "Saturno e Lua", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Saturno", "Lua"], "signosChave": []}, {"nome": "Loureiro-comum", "cientifico": "Laurus nobilis", "usosMedicinais": "Carminativo, digestivo, estomacal e nervino, em infusão de folhas; também em injeções vaginais e banhos. Antigo livro de medicina recomenda as folhas frescas trituradas contra mordidas venenosas.", "ocultismo": "Árvore consagrada a Apolo. A dafnomancia era forma de adivinhação que usava ramos de loureiro queimados (pelo crepitar e fumaça) ou mastigados (pelos sacerdotes chamados dafnéfagos) para obter presságios e respostas.", "planeta": "Sol e Lua", "signo": "Leão ou Peixes", "colheita": "", "elemento": "Quente e seco", "planetasChave": ["Sol", "Lua"], "signosChave": ["Leão", "Peixes"]}, {"nome": "Lúpulo", "cientifico": "Humulus lupulus", "usosMedicinais": "Amargo, sedativo e anafrodisíaco; favorece a digestão; bom contra insônia nervosa, escrófula, linfatismo e infartos hepáticos; o lupulino (pó dos conos) é prescrito contra a espermatorreia.", "ocultismo": "", "planeta": "Saturno e Lua", "signo": "", "colheita": "Conos colhidos em fins de agosto.", "elemento": "", "planetasChave": ["Saturno", "Lua"], "signosChave": []}, {"nome": "Macela", "cientifico": "Anthemis nobilis", "usosMedicinais": "Conhecida como macela-romana ou camomila. Tônica, antiespasmódica e anti-histérica, em infusão das flores; contra cólicas e excitação nervosa.", "ocultismo": "Levemente quente e úmida.", "planeta": "Sol", "signo": "Libra", "colheita": "", "elemento": "Levemente quente e úmida", "planetasChave": ["Sol"], "signosChave": ["Libra"]}, {"nome": "Macieira", "cientifico": "Pyrus malus", "usosMedicinais": "A casca da raiz fresca corta acessos de febre; a polpa do fruto assado, em cataplasmas, combate furúnculos.", "ocultismo": "Árvore consagrada a Ceres. O tratado de onirocrítica de Artemídoro de Daldia interpreta longamente sonhos com maçãs conforme a profissão de quem sonha e o estado do fruto.", "planeta": "O fruto: Vênus", "signo": "Talo: Escorpião; folhas: Gêmeos e Virgem", "colheita": "", "elemento": "Frio e levemente seco", "planetasChave": ["Vênus"], "signosChave": ["Gêmeos", "Virgem", "Escorpião"]}, {"nome": "Mandrágora", "cientifico": "Panax quinquefolium", "usosMedicinais": "Pouco usada em medicina.", "ocultismo": "Conhecida pelos hebreus como Jabora; entra na composição da pomada dos bruxos para o Sabá. Sua raiz, de forma humanoide, é considerada poderoso condensador de forças astrais e usada (segundo o livro) por magos negros, inclusive na fabricação de homúnculos. A crença popular diz que grita quando arrancada do solo. Amplamente descrita por H.P. Blavatsky e por Collin de Plancy como talismã de fertilidade e fortuna, associada a rituais envolvendo um cão para a extração.", "planeta": "Saturno", "signo": "Capricórnio", "colheita": "", "elemento": "", "planetasChave": ["Saturno"], "signosChave": ["Capricórnio"]}, {"nome": "Marroio-branco", "cientifico": "Marrubium vulgare", "usosMedicinais": "Estimulante, reconstituinte, laxante, diaforético e bom tônico digestivo; bons resultados em afecções respiratórias, tosse rebelde e tuberculose; uso prolongado combate obesidade. O suco em unturas detém a queda de cabelo.", "ocultismo": "Colhe-se sob o signo de Virgem.", "planeta": "", "signo": "Virgem", "colheita": "", "elemento": "", "planetasChave": [], "signosChave": ["Virgem"]}, {"nome": "Meimendro negro", "cientifico": "Hyosciamus niger", "usosMedicinais": "Quente e seco. Planta perigosa, de uso reservado a médicos; em azeite, contra reumatismo articular e neuralgias; as sementes em defumação acalmam dor de dentes e frieiras; seu cheiro prolongado provoca forte entorpecimento.", "ocultismo": "O fumo de suas semelhantes, colhidas e queimadas na hora de Saturno, provoca discórdias e rixas, e era usado por feiticeiros para causar dano à distância. Compõe a tradicional pomada das bruxas.", "planeta": "Saturno", "signo": "", "colheita": "Hora de Saturno.", "elemento": "Quente e seco", "planetasChave": ["Saturno"], "signosChave": []}, {"nome": "Melissa", "cientifico": "Melissa officinalis", "usosMedicinais": "Conhecida como erva-cidreira. Usada contra histerismo, hipocondria, estados espasmódicos, desfalecimentos, vertigens, enxaquecas e atonia estomacal, em infusão; em loções, fortalece a vista e cura chagas.", "ocultismo": "As sibilas dos templos antigos (Cumas, Delfos, etc.) usavam beberagem com melissa para despertar sua inspiração. Tradição diz que um boi seguirá obedientemente quem lhe pendurar um ramo no pescoço.", "planeta": "Sol e Júpiter", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Júpiter", "Sol"], "signosChave": []}, {"nome": "Mercurial", "cientifico": "Mercurialis annua", "usosMedicinais": "Usada fresca; laxante e, em grandes doses, purgativa; bom diurético contra hidropisia; também contra lombrigas e hemorroidas incipientes; detém a secreção láctea.", "ocultismo": "Fria e úmida. Seu suco em decocção, segundo a crença, favorece a concepção de um filho (planta macho) ou filha (planta fêmea), usado pela mulher durante cinco dias.", "planeta": "Lua", "signo": "Virgem", "colheita": "", "elemento": "Fria e úmida", "planetasChave": ["Lua"], "signosChave": ["Virgem"]}, {"nome": "Mil-folhas", "cientifico": "Achillea Millefolium", "usosMedicinais": "A raiz, de cheiro alcanforado, usada em infusão fresca; folhas e flores são adstringentes, úteis em hemorroidas, hemorragias uterinas e hemoptises; em decocto, cicatriza feridas.", "ocultismo": "", "planeta": "Sol e Lua", "signo": "Câncer", "colheita": "", "elemento": "", "planetasChave": ["Sol", "Lua"], "signosChave": ["Câncer"]}, {"nome": "Mirra", "cientifico": "Myrrha Commyfora abissynica", "usosMedicinais": "Campo terapêutico reduzido; em pó, sobre úlceras cancerosas; em defumação, desinfeta o quarto de doentes.", "ocultismo": "Segundo a mitologia, surgiu das lágrimas da deusa Mirra. Van Helmont afirmava que diluída em álcool prolonga a vida. Muito usada em trabalhos de alta magia, teúrgicos e goéticos, misturada com estoraque, benjoim, incenso e cascarilha.", "planeta": "Vênus", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Vênus"], "signosChave": []}, {"nome": "Morangueiro", "cientifico": "Fragaria vesca", "usosMedicinais": "Usam-se frutos e raízes. O xarope é refrescante, indicado contra icterícia e mal de pedra; o decocto da raiz, contra disenterias, diarreias, hemorragias e gonorreias leves.", "ocultismo": "Cintos feitos com suas folhas preservam contra picadas de cobra.", "planeta": "Júpiter", "signo": "Peixes", "colheita": "", "elemento": "", "planetasChave": ["Júpiter"], "signosChave": ["Peixes"]}, {"nome": "Murta", "cientifico": "Myrtus communis", "usosMedicinais": "Recomendada para cicatrizar contusões e chagas, em pó ou decocto; os vapores de sua infusão aliviam enxaqueca; o fruto, em emplasto, detém vômitos.", "ocultismo": "Fria e seca. Consagrada a Vênus e aos deuses penates; emblema da compaixão. Misturada com cipreste seco e incenso macho, forma perfumes mágicos para atrair entidades astrais e é usada em trabalhos de magia erótica.", "planeta": "Vênus", "signo": "Touro", "colheita": "", "elemento": "Fria e seca", "planetasChave": ["Vênus"], "signosChave": ["Touro"]}, {"nome": "Musgo", "cientifico": "Fucus purpureus", "usosMedicinais": "Usado contra lombrigas de crianças, em pó ou decocto com água ou leite; em decocção, detém a queda de cabelo, reforça a dentadura e corta fluxos de sangue.", "ocultismo": "", "planeta": "Saturno", "signo": "", "colheita": "", "elemento": "", "planetasChave": ["Saturno"], "signosChave": []}, {"nome": "Nabo", "cientifico": "Brassica napus", "usosMedicinais": "Cozido e aplicado atrás das orelhas, acalma dor de dentes; em cataplasma, alivia coceira de frieiras; a raiz em decocção trata catarro, bronquite e tosse ferina.", "ocultismo": "", "planeta": "Lua", "signo": "Capricórnio", "colheita": "", "elemento": "", "planetasChave": ["Lua"], "signosChave": ["Capricórnio"]}, {"nome": "Narciso", "cientifico": "Narcissus pseudonarcissus", "usosMedicinais": "Antiespasmódico, adstringente, emético e febrífugo; usado contra tosses nervosas e coqueluche; as flores dessecadas (que mantêm sua cor) são antiespasmódicas e narcóticas, com relato de uso bem-sucedido contra convulsões.", "ocultismo": "Frio e seco. Os antigos dedicavam-no às Fúrias e a Plutão. Quem o leva consigo atrai a amizade das virgens.", "planeta": "Vênus", "signo": "Touro e Leão", "colheita": "", "elemento": "Frio e seco", "planetasChave": ["Vênus"], "signosChave": ["Touro", "Leão"]}, {"nome": "Nogueira", "cientifico": "Juglans regia", "usosMedicinais": "As folhas frescas, em infusão, combatem escrófulas e icterícia; em injeções vaginais, curam leucorreia; em loção, evitam a queda de cabelo. Seu cheiro atrai pulgas.", "ocultismo": "", "planeta": "Lua", "signo": "Sagitário", "colheita": "", "elemento": "", "planetasChave": ["Lua"], "signosChave": ["Sagitário"]}, {"nome": "Oliveira", "cientifico": "Olea europea", "usosMedicinais": "Usam-se folhas, casca e azeite. A infusão de folhas e casca lava chagas e expulsa lombrigas; o azeite puro é excelente laxante e alivia cólicas hepáticas e nefrites; misturado a gema de ovo, alivia queimaduras.", "ocultismo": "Consagrada à deusa Minerva; um ramo é emblema da paz. O azeite é considerado poderoso condensador de luz, usado em diversos trabalhos mágicos — como escrever a palavra ATHNA numa folha presa à cabeça para dissipar inquietude e maus pensamentos.", "planeta": "Júpiter", "signo": "Peixes", "colheita": "", "elemento": "", "planetasChave": ["Júpiter"], "signosChave": ["Peixes"]}, {"nome": "Tanchagem", "cientifico": "Plantago major", "usosMedicinais": "Folhas adstringentes, usadas em gargarejos para inflamações da boca e, em loção, dos olhos; bom peitoral em catarros bronquiais; trituradas, cicatrizam úlceras e feridas. A raiz é boa contra enxaqueca e contraveneno do ópio com vinho.", "ocultismo": "Quente e levemente úmida. Trazida consigo, a planta inteira preserva de malefícios.", "planeta": "Sol", "signo": "Áries e Leão", "colheita": "Quando Sol e Lua estão em Câncer, ou Sol em Peixes e Lua em Câncer.", "elemento": "Quente e levemente úmida", "planetasChave": ["Sol"], "signosChave": ["Áries", "Leão"]}, {"nome": "Urupê", "cientifico": "Polyporus officinalis", "usosMedicinais": "Fungo que cresce em troncos de árvores; vermífugo, peitoral e emenagogo; purgante que pode causar cólicas violentas.", "ocultismo": "Propriedades mágicas desconhecidas.", "planeta": "Lua", "signo": "", "colheita": "", "elemento": "Quente, entre seco e úmido", "planetasChave": ["Lua"], "signosChave": []}];